 <div id="hint">WASD / arrows move · mouse drag to look · SPACE jump · E enter car · CLICK fire</div>
 <div id="startScreen"><div class="startCard"><div class="brand">NEON <span>VICE</span></div><div class="sub">LEONIDA · AFTER DARK</div><p class="copy">A neon-soaked night in the city. Grab the drop, keep moving, and make it out with the cash.</p><div class="missionCard"><strong>YOUR FIRST JOB</strong><p>Find the glowing pink pickup in the plaza. Watch your surroundings — trouble is never far away.</p></div><button id="startBtn" class="startBtn">ENTER THE CITY</button><div class="keys">WASD move · Mouse drag look · E enter/exit · Space jump · Click fire</div></div></div>
 <script>
+(()=>{
+const $=s=>document.querySelector(s), scene=new THREE.Scene();scene.background=new THREE.Color(0x080d1b);scene.fog=new THREE.FogExp2(0x080d1b,.009);
+const renderer=new THREE.WebGLRenderer({canvas:$('#scene'),antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputEncoding=THREE.sRGBEncoding;
+const camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.1,320);scene.add(new THREE.HemisphereLight(0x91cfff,0x151024,1.55));const moon=new THREE.DirectionalLight(0xc5ddff,1.35);moon.position.set(-30,60,25);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);scene.add(moon);
+const mat=(color,emissive=0x000000,intensity=0)=>new THREE.MeshStandardMaterial({color,roughness:.72,metalness:.12,emissive,emissiveIntensity:intensity});
+const asphalt=mat(0x171d2b),sidewalk=mat(0x343448),concrete=mat(0x777d8c),white=mat(0xe4f6ff,0x1e5473,.45),pink=mat(0xff329b,0xff1687,2),cyan=mat(0x2beaff,0x0ccfff,1.7),gold=mat(0xffca64,0xffa51b,.9),dark=mat(0x101827),skin=mat(0xe6a57b),cloth=mat(0x21172c),lime=mat(0x9cff73,0x45ff23,.7);
+function box(parent,x,y,z,w,h,d,m){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
+const ground=new THREE.Mesh(new THREE.PlaneGeometry(300,300),mat(0x111626));ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
+// Street grid, sidewalks, lane dashes, and warm streetlamps.
+for(let v=-84;v<=84;v+=28){box(scene,v,.01,0,10,.08,190,asphalt);box(scene,0,.012,v,190,.08,10,asphalt);box(scene,v+6,.02,0,2,.12,190,sidewalk);box(scene,v-6,.02,0,2,.12,190,sidewalk);box(scene,0,.02,v+6,190,.12,2,sidewalk);box(scene,0,.02,v-6,190,.12,2,sidewalk);
+ for(let t=-88;t<90;t+=10){box(scene,v,.075,t, .13,.025,4,white);box(scene,t,.075,v,4,.025,.13,white)}
+ for(const side of [-1,1])for(const axis of ['x','z']){let lx=axis==='x'?v+side*7.7:t=>(t);let z=axis==='z'?v+side*7.7:0;for(let t=-70;t<=70;t+=28){let x=axis==='x'?lx:t,zp=axis==='z'?z:t;box(scene,x,3.8,zp,.12,7.6,.12,mat(0x74849b));box(scene,x,7.55,zp,2,.12,.12,mat(0x74849b));const bulb=new THREE.PointLight(0xffb166,.55,13);bulb.position.set(x,7,zp);scene.add(bulb);const lamp=new THREE.Mesh(new SphereGeometry(.18,8,8),gold);lamp.position.copy(bulb.position);scene.add(lamp)}}
+// Buildings fill the blocks between streets. Windows and roof signs create a colorful skyline.
+let seed=1753;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
+for(let gx=-70;gx<=70;gx+=28)for(let gz=-70;gz<=70;gz+=28){if(Math.abs(gx)<16&&Math.abs(gz)<16)continue;let w=12+rand()*6,d=12+rand()*6,h=9+rand()*27,x=gx+(rand()-.5)*5,z=gz+(rand()-.5)*5;let hue=[0x182338,0x222136,0x1b2c3b,0x302039,0x242b3d][Math.floor(rand()*5)];box(scene,x,h/2,z,w,h,d,mat(hue));let roof=box(scene,x,h+.15,z,w+.18,.3,d+.18,mat(0x465167));roof.castShadow=false;
+ const edgeMat=rand()>.5?pink:cyan;box(scene,x-w/2,h*.55,z,d*.0+.06,.1,d,edgeMat);if(rand()>.36){box(scene,x,h+1,z,w*.55,.6,.35,edgeMat);const sign=box(scene,x,h+1.04,z-.21,w*.48,.18,.04,mat(0xffffff,rand()>.5?0xff178a:0x00dfff,2));}
+ for(let yy=3;yy<h-1;yy+=3.3)for(let xx=-w/2+1.3;xx<w/2-1;xx+=2.6){if(rand()>.2){let win=box(scene,x+xx,yy,z-d/2-.035,1.05,1.15,.06,rand()>.76?pink:(rand()>.5?cyan:mat(0x3c6171,0x163850,.8)));win.castShadow=false}}
+}
+// Central plaza and neon objective marker.
+const plaza=box(scene,0,-.015,-18,13,.08,15,mat(0x303447));
+function makeMarker(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);let tor=new THREE.Mesh(new THREE.TorusGeometry(1.7,.1,8,32),pink);tor.rotation.x=Math.PI/2;tor.position.y=.2;g.add(tor);let beam=new THREE.Mesh(new THREE.CylinderGeometry(.06,.3,4,12,1,true),new THREE.MeshBasicMaterial({color:0xff2494,transparent:true,opacity:.22,side:THREE.DoubleSide}));beam.position.y=2;g.add(beam);let spr=new THREE.Mesh(new THREE.OctahedronGeometry(.42),gold);spr.position.y=1.2;g.add(spr);g.userData={tor,spr};return g}const objective=makeMarker(0,-18);
+// A stylized third-person character.
+const player=new THREE.Group();scene.add(player);const avatar=new THREE.Group();player.add(avatar);box(avatar,0,1.05,0,.75,1.05,.42,cloth);box(avatar,0,1.82,0,.44,.47,.42,skin);box(avatar,0,2.1,0,.52,.16,.5,mat(0x141521));box(avatar,-.49,1.1,0,.22,.85,.25,skin);box(avatar,.49,1.1,0,.22,.85,.25,skin);box(avatar,-.2,.35,0,.24,.68,.28,dark);box(avatar,.2,.35,0,.24,.68,.28,dark);box(avatar,-.2,.08,.12,.3,.16,.48,cyan);box(avatar,.2,.08,.12,.3,.16,.48,pink);player.position.set(0,0,10);
+// Neon coupe parked at the edge of the plaza.
+function makeCar(x,z,color=0x982454){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);box(g,0,.65,0,2.1,.65,4.2,mat(color));box(g,0,1.15,-.15,1.6,.68,2.1,mat(0x172b42));box(g,0,1.5,1.55,1.5,.1,.06,white);box(g,-.85,.44,2.09,.32,.2,.06,white);box(g,.85,.44,2.09,.32,.2,.06,white);for(let sx of [-1,1])for(let sz of [-1,1]){let wh=new THREE.Mesh(new THREE.CylinderGeometry(.34,.34,.18,12),mat(0x101116));wh.rotation.z=Math.PI/2;wh.position.set(sx*.98,.35,sz*1.35);g.add(wh)}g.userData={speed:0,occupied:false};return g}const cars=[makeCar(5,-9),makeCar(-12,15,0x147b8b),makeCar(30,-3,0x555e87)];
+// Hostiles are intentionally arcade-like silhouettes, not realistic characters.
+const enemies=[];function makeEnemy(x,z){let e=new THREE.Group();scene.add(e);box(e,0,.9,0,.68,.95,.4,mat(0x532139));box(e,0,1.65,0,.42,.42,.4,mat(0x9c6e5c));box(e,0,1.84,0,.45,.12,.44,dark);e.position.set(x,0,z);e.userData={hp:2,cd:0};enemies.push(e);return e}makeEnemy(11,2);makeEnemy(-11,-9);makeEnemy(18,-22);
+// Pickups and city details.
+const pickups=[];function addPickup(x,z){let g=new THREE.Group();g.position.set(x,.8,z);scene.add(g);let gem=new THREE.Mesh(new THREE.OctahedronGeometry(.45),gold);g.add(gem);const light=new THREE.PointLight(0xffb92e,1.2,8);light.position.y=1;g.add(light);pickups.push(g)}addPickup(7,7);addPickup(-19,-8);addPickup(32,23);
+// Star field and decorative palm trunks in the open plaza.
+for(let i=0;i<220;i++){let s=new THREE.Mesh(new THREE.SphereGeometry(.12+rand()*.22,5,5),new THREE.MeshBasicMaterial({color:rand()>.5?0x72c8ff:0xff86bf,transparent:true,opacity:.4+rand()*.5}));s.position.set((rand()-.5)*220,12+rand()*45,(rand()-.5)*220);scene.add(s)}

