for(let i=0;i<220;i++){let s=new THREE.Mesh(new THREE.SphereGeometry(.12+rand()*.22,5,5),new THREE.MeshBasicMaterial({color:rand()>.5?0x72c8ff:0xff86bf,transparent:true,opacity:.4+rand()*.5}));s.position.set((rand()-.5)*220,12+rand()*45,(rand()-.5)*220);scene.add(s)}
const state={started:false,hp:100,armor:55,cash:500,ammo:12,reserve:48,wanted:0,mission:0,fire:false,jump:false,driving:null,toastTimer:0,shotCd:0,damageCd:0,joyX:0,joyY:0};let yaw=0,camYaw=0,camPitch=.22,clock=new THREE.Clock(),toastTimer=0,keys={},bullets=[],enemyShots=[],radioIndex=0,ac=null;
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}function updateUI(){ $('#cash').textContent=String(state.cash).padStart(6,'0');$('#hp').style.width=state.hp+'%';$('#armor').style.width=state.armor+'%';$('#ammo').textContent=state.ammo+' / '+state.reserve;$('#stars').innerHTML=Array.from({length:5},(_,i)=>`<span class="${i<state.wanted?'on':''}">★</span>`).join('') }
function sound(freq=440,duration=.08,type='sine'){try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();let o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.08,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch(e){}}
function setPrompt(text){let p=$('#prompt');p.textContent=text;p.classList.toggle('show',!!text)}
function doJump(){if(!state.started)return;if(state.driving){toast('Hit the gas and cruise.');return}if(!player.userData.vy)player.userData.vy=.17;sound(220,.09)}
function fireShot(){if(!state.started||state.driving||state.shotCd>0)return;if(state.ammo<=0){if(state.reserve){state.ammo=12;state.reserve=Math.max(0,state.reserve-12);toast('RELOADED');sound(180,.13)}else toast('OUT OF AMMO');updateUI();state.shotCd=.3;return}state.ammo--;state.shotCd=.22;state.wanted=Math.min(5,Math.max(1,state.wanted));sound(145,.11,'sawtooth');
 const origin=player.position.clone().add(new THREE.Vector3(0,1.35,0));const aim=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));let target=null,best=24;for(const e of enemies){if(e.userData.hp<=0)continue;let d=e.position.clone().sub(player.position),dist=d.length(),dot=d.normalize().dot(aim);if(dist<best&&dot>.68){target=e;best=dist}}let end=target?target.position.clone().add(new THREE.Vector3(0,1,0)):origin.clone().add(aim.multiplyScalar(24));let line=new THREE.BufferGeometry().setFromPoints([origin,end]);let beam=new THREE.Line(line,new THREE.LineBasicMaterial({color:0xffdf8b,transparent:true,opacity:.95}));scene.add(beam);setTimeout(()=>{scene.remove(beam);line.dispose()},65);
 if(target){target.userData.hp--;let glow=new THREE.PointLight(0xff285f,1.5,4);glow.position.copy(target.position).add(new THREE.Vector3(0,1,0));scene.add(glow);setTimeout(()=>scene.remove(glow),90);if(target.userData.hp<=0){target.visible=false;state.cash+=100;toast('THREAT CLEARED  +$100');sound(620,.12)}else toast('TARGET HIT')}updateUI()}
function nearestCar(){let best=null,dist=4.5;for(const c of cars){let d=c.position.distanceTo(player.position);if(d<dist){best=c;dist=d}}return best}
function interact(){if(!state.started)return;if(state.driving){let c=state.driving;state.driving=null;c.userData.occupied=false;player.visible=true;player.position.copy(c.position).add(new THREE.Vector3(2,0,0));toast('BACK ON FOOT');sound(340,.08);return}let c=nearestCar();if(c){state.driving=c;c.userData.occupied=true;player.visible=false;toast('VEHICLE ACQUIRED · DRIVE');sound(480,.12);return}if(player.position.distanceTo(objective.position)<3.7&&state.mission===0){state.mission=1;state.cash+=1500;state.wanted=Math.max(1,state.wanted);objective.visible=false;$('#missionName').textContent='CONTRACT COMPLETE';$('#missionDesc').textContent='Package secured. Collect cash and explore the city.';$('#missionProgress').style.width='100%';toast('DROP COMPLETE  +$1,500');sound(760,.25);updateUI();return}toast('NOTHING TO INTERACT WITH')}
$('#startBtn').addEventListener('click',()=>{$('#startScreen').classList.add('hide');state.started=true;toast('WELCOME TO LEONIDA');sound(520,.18)});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyE')interact();if(e.code==='Space'&&!e.repeat)doJump();if(e.code==='KeyR'){state.ammo=12;state.reserve=Math.max(0,state.reserve-12);updateUI()}});window.addEventListener('keyup',e=>keys[e.code]=false);
let drag=null;renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&state.started){drag={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId)}});renderer.domElement.addEventListener('pointermove',e=>{if(drag){camYaw-=(e.clientX-drag.x)*.006;camPitch=Math.max(-.05,Math.min(.72,camPitch+(e.clientY-drag.y)*.003));drag={x:e.clientX,y:e.clientY}}});renderer.domElement.addEventListener('pointerup',()=>drag=null);
const joy=$('#joy'),knob=$('#knob');let joyPointer=null;joy.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)joyMove(e)});function joyMove(e){let r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),lim=r.width*.31,l=Math.hypot(dx,dy);if(l>lim){dx*=lim/l;dy*=lim/l}state.joyX=dx/lim;state.joyY=dy/lim;knob.style.transform=`translate(${dx}px,${dy}px)`}function endJoy(){joyPointer=null;state.joyX=state.joyY=0;knob.style.transform='translate(0,0)'}joy.addEventListener('pointerup',endJoy);joy.addEventListener('pointercancel',endJoy);
function bindHold(id,down,up=()=>{}){let b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();b.classList.add('pressed');down();if(id==='#fire')state.fire=true});const stop=e=>{e.preventDefault();b.classList.remove('pressed');if(id==='#fire')state.fire=false;up()};b.addEventListener('pointerup',stop);b.addEventListener('pointercancel',stop);b.addEventListener('contextmenu',e=>e.preventDefault())}
bindHold('#fire',fireShot);bindHold('#jump',doJump);bindHold('#interact',interact);$('#radio').addEventListener('click',()=>{radioIndex=(radioIndex+1)%4;$('#station').innerHTML=['♫ &nbsp;LEONIDA FM · 104.2','♫ &nbsp;VICE WAVE · 98.6','♫ &nbsp;NIGHT DRIVE · 91.3','♫ &nbsp;OFF AIR'][radioIndex];sound(300+radioIndex*90,.12)});window.addEventListener('pointerdown',e=>{if(state.started&&e.target===$('#scene')&&e.pointerType==='mouse'&&e.button===0)fireShot()});

